import{_ as t,o as r,c as o,ak as a}from"./chunks/framework.sV-XtlWr.js";const m=JSON.parse('{"title":"Clue rules","description":"Every rule that can produce a clue on a failing execution, its strength and when it fires, and the stories that chain several clues into one sentence.","frontmatter":{"title":"Clue rules","description":"Every rule that can produce a clue on a failing execution, its strength and when it fires, and the stories that chain several clues into one sentence.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/clues.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/clues.html"}],["meta",{"property":"og:title","content":"Clue rules | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Every rule that can produce a clue on a failing execution, its strength and when it fires, and the stories that chain several clues into one sentence."}]]},"headers":[],"relativePath":"reference/clues.md","filePath":"reference/clues.md","lastUpdated":1791474596000}'),d={name:"reference/clues.md"};function s(n,e,i,l,h,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="clue-rules" tabindex="-1">Clue rules <a class="header-anchor" href="#clue-rules" aria-label="Permalink to &quot;Clue rules&quot;">​</a></h1><p>A <strong>clue</strong> is a one-line finding a deterministic rule draws from the evidence Piwi already stores for a failing execution; no model is involved. The <strong>Most likely</strong> line of the <a href="/guide/first-failure.html#_2-most-likely-why">situation block</a> leads with the strongest clue or the story it belongs to, and the same clues are handed to the <a href="/features/ai-diagnosis.html">AI diagnosis</a> as evidence to confirm or refute. What a clue is on the page is described on <a href="/features/evidence.html#clues">Failure evidence</a>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p>Each rule emits at most one clue (two for a failed request), with a strength and a citation to the evidence section it came from. The <strong>failure window</strong> is the timeline&#39;s default view: from 10 seconds before the failed step to 2 seconds after it.</p><table tabindex="0"><thead><tr><th>Rule</th><th>Strength</th><th>Fires when</th></tr></thead><tbody><tr><td>Failed request before the failure<br><code>failed-request-before-failure</code></td><td>strong</td><td>A request returned 5xx, or failed without a response (the clue names the browser&#39;s error, such as <code>net::ERR_CONNECTION_RESET</code>), in the 10 seconds before the moment of failure.</td></tr><tr><td>Slow request overlapping the failure<br><code>slow-request-overlapping-failure</code></td><td>medium</td><td>A request slower than <code>PIWI_AI_SLOW_REQUEST_MS</code> (default 1,500 ms) was still in flight during the failed step.</td></tr><tr><td>Console mentions the target<br><code>console-mentions-target</code></td><td>strong for an error, medium for a warning</td><td>A console entry in the failure window names the failing locator or route.</td></tr><tr><td>Dialog open at the failure<br><code>dialog-open-on-failure</code></td><td>strong</td><td>A browser dialog (<code>alert</code>, <code>confirm</code>, <code>prompt</code>, <code>beforeunload</code>) closed in the failure window, so it was open when the action ran. Needs Playwright 1.63 or later.</td></tr><tr><td>Backend error attached<br><code>backend-error-attached</code></td><td>strong</td><td>A request in the failure window carries an error-level <a href="/guide/backend-logs.html">backend log</a>.</td></tr><tr><td>Element renamed<br><code>element-renamed</code></td><td>strong</td><td><a href="/features/locator-healing.html">Locator healing</a> found the element under a new identity, or flagged the stored name as stale while still recommending a fix.</td></tr><tr><td>Page structure changed near the failing locator<br><code>page-structure-changed</code></td><td>strong when the locator never resolved, else medium</td><td>The <a href="/features/evidence.html#page-diff">page diff</a> against the last green sample shows the element the locator names was removed or renamed.</td></tr><tr><td>Element present but blocked<br><code>element-present-but-blocked</code></td><td>strong</td><td>The call log says the element resolved but was disabled, hidden, not visible or covered by another element, and the ARIA snapshot still shows it.</td></tr><tr><td>Wrong page<br><code>wrong-page</code></td><td>strong</td><td>The page ended on a login, sign-in, auth, error, 404 or not-found route, or somewhere other than the last navigation the test asked for. The end URL comes from the captured app state, else from the last navigation step.</td></tr><tr><td>Worker pollution<br><code>worker-pollution</code></td><td>medium</td><td>The previous test on the same worker failed, timed out or was interrupted.</td></tr><tr><td>Previous lock holder failed<br><code>lock-holder-failed</code></td><td>strong</td><td>The execution that held the same <a href="/reference/test-metadata.html#test-locks">lock</a> just before this test, in this run, failed or timed out.</td></tr><tr><td>Lock held on two shards<br><code>lock-cross-shard</code></td><td>medium</td><td>A lock this test held overlapped in time with a holder on another shard. Locks serialize only within one <code>playwright test</code> process.</td></tr><tr><td>Timeout budget<br><code>timeout-budget</code></td><td>medium</td><td>The failed step used at least 80 % of the test timeout, or the execution used at least 95 %.</td></tr><tr><td>Environment changed<br><code>environment-changed</code></td><td>medium when the browser, channel, viewport, locale, timezone, base URL or environment label changed, else weak</td><td>The environment differs from the same test&#39;s last green run in the same environment. Tool versions and color scheme alone stay weak.</td></tr><tr><td>Browser-specific<br><code>browser-specific</code></td><td>medium</td><td>The same test passed on at least one other browser in this run.</td></tr><tr><td>Known flake suspect<br><code>known-flake-suspect</code></td><td>strong when a <a href="/features/flake-lab.html">Flake Lab</a> experiment reproduced the suspect, else weak</td><td>This failure shows one of its test&#39;s <a href="/features/flaky-tests.html#suspects">suspects</a>, when it shows several, the one an experiment reproduced, else the highest ranked: a slow or failed route, a test alongside or just before, load or a browser. The detail gives this failure&#39;s value and the suspect&#39;s counts, and, once reproduced, the arm against its control (&quot;3 of 4 under delay GET /api/cart 1.8 s, against 0 of 10 without&quot;).</td></tr></tbody></table><p>Clues are ranked by strength, then by membership of the story, then by how close they sit to the moment of failure, and the list is capped at eight. An earlier fix that regressed is not a clue: the situation sentence carries it.</p><h2 id="stories" tabindex="-1">Stories <a class="header-anchor" href="#stories" aria-label="Permalink to &quot;Stories&quot;">​</a></h2><p>When several clues form a known combination, they are chained into one <strong>story</strong> sentence at the strongest member&#39;s strength. The first combination that matches, in this order, wins:</p><table tabindex="0"><thead><tr><th>Story</th><th>Clues it chains</th><th>Example sentence</th></tr></thead><tbody><tr><td>Blocked by a pending request</td><td>element present but blocked, with a slow or failed request, and the console clue when present</td><td><em>The button &quot;Pay&quot; stayed disabled because POST /api/checkout/quote was still in flight (28 s).</em></td></tr><tr><td>Renamed</td><td>element renamed and page structure changed</td><td><em>The button the locator names was renamed from &quot;Pay&quot; to &quot;Pay now&quot; since the last pass.</em></td></tr><tr><td>Removed</td><td>page structure changed, without element renamed</td><td><em>The button &quot;Pay&quot; is no longer on the page since the last pass.</em></td></tr><tr><td>Wrong page</td><td>wrong page, with a failed request or an open dialog</td><td><em>The test ended on /login instead of /checkout after the request.</em></td></tr><tr><td>Polluted worker</td><td>worker pollution, and the lock holder clue when present</td><td><em>The previous test on this worker failed and left state behind.</em></td></tr><tr><td>Backend error</td><td>backend error attached, with a failed or slow request</td><td><em>POST /api/orders failed on the server.</em></td></tr><tr><td>Timing</td><td>timeout budget and slow request</td><td><em>The step used 92 % of the timeout waiting on /api/search.</em></td></tr></tbody></table><p>When no combination matches, the strongest clue stands alone. A cluster&#39;s completed AI diagnosis leads instead of a lone clue, and the clues then read as <em>supported by N clues</em>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/evidence.html#clues">Failure evidence</a>: where the clues appear, with the evidence they cite</li><li><a href="/guide/first-failure.html">Your first failure, explained</a>: the situation block the <strong>Most likely</strong> line belongs to</li><li><a href="/guide/concepts.html#story">Core concepts</a>: the story</li></ul>',12)])])}const f=t(d,[["render",s]]);export{m as __pageData,f as default};
